export interface INewEditSessionActionContext {

	/**
	 * An initial prompt to write to the chat.
	 */
	inputValue?: string;

	/**
	 * Selects opening in agent mode or not. If not set, the current mode is used.
	 * This is ignored when coming from a chat view title context.
	 */
	agentMode?: boolean;

	/**
	 * Whether the inputValue is partial and should wait for further user input.
	 * If false or not set, the prompt is sent immediately.
	 */
	isPartialQuery?: boolean;
}

function isNewEditSessionActionContext(arg: unknown): arg is INewEditSessionActionContext {
	if (arg && typeof arg === 'object') {
		const obj = arg as Record<string, unknown>;
		if (obj.inputValue !== undefined && typeof obj.inputValue !== 'string') {
			return false;
		}
		if (obj.agentMode !== undefined && typeof obj.agentMode !== 'boolean') {
			return false;
		}
		if (obj.isPartialQuery !== undefined && typeof obj.isPartialQuery !== 'boolean') {
			return false;
		}
		return true;
	}
	return false;
}

export function registerNewChatActions() {

	// Add "New Chat" submenu to Chat view menu
	MenuRegistry.appendMenuItem(MenuId.ViewTitle, {
		submenu: MenuId.ChatNewMenu,
		title: localize2('chat.newEdits.label', "New Chat"),
		icon: Codicon.plus,
		when: ContextKeyExpr.equals('view', ChatViewId),
		group: 'navigation',
		order: -1,
		isSplitButton: true
	});

	registerAction2(class NewChatEditorAction extends Action2 {
		constructor() {
			super({
				id: 'workbench.action.chatEditor.newChat',
				title: localize2('chat.newChat.label', "New Chat"),
				icon: Codicon.plus,
				f1: false,
				precondition: ChatContextKeys.enabled,
			});
		}
		async run(accessor: ServicesAccessor, ...args: unknown[]) {
			await clearChatEditor(accessor);
		}
	});

	registerAction2(class NewChatAction extends Action2 {
		constructor() {
			super({
				id: ACTION_ID_NEW_CHAT,
				title: localize2('chat.newEdits.label', "New Chat"),
				category: CHAT_CATEGORY,
				icon: Codicon.plus,
				precondition: ContextKeyExpr.and(ChatContextKeys.enabled, ChatContextKeys.location.isEqualTo(ChatAgentLocation.Chat)),
				f1: true,
				menu: [
					{
						id: MenuId.ChatContext,
						group: 'z_clear'
					},
					{
						id: MenuId.ChatNewMenu,
						group: '1_open',
						order: 1,
						when: ContextKeyExpr.and(
							ChatContextKeys.newChatButtonExperimentIcon.notEqualsTo('copilot'),
							ChatContextKeys.newChatButtonExperimentIcon.notEqualsTo('new-session'),
							ChatContextKeys.newChatButtonExperimentIcon.notEqualsTo('comment')
						)
					}
				],
				keybinding: {
					weight: KeybindingWeight.WorkbenchContrib + 1,
					primary: KeyMod.CtrlCmd | KeyCode.KeyN,
					secondary: [KeyMod.CtrlCmd | KeyCode.KeyL],
					mac: {
						primary: KeyMod.CtrlCmd | KeyCode.KeyN,
						secondary: [KeyMod.WinCtrl | KeyCode.KeyL]
					},
					when: ChatContextKeys.inChatSession
				}
			});
		}

		async run(accessor: ServicesAccessor, ...args: unknown[]) {
			const executeCommandContext = isNewEditSessionActionContext(args[0]) ? args[0] : undefined;
			// Do not depend on getEditingSessionContext — it returns undefined when
			// the chat pane has no viewModel yet (empty / sessions list), which made
			// New Chat appear to do nothing. Always create a local empty composer.
			await runNewChatAction(accessor, undefined, executeCommandContext, AgentSessionProviders.Local);
		}
	}
	);

	const iconVariants = [
		{ idSuffix: '.copilotIcon', iconValue: 'copilot', icon: Codicon.copilot },
		{ idSuffix: '.newSessionIcon', iconValue: 'new-session', icon: Codicon.newSession },
		{ idSuffix: '.commentIcon', iconValue: 'comment', icon: Codicon.comment },
	] as const;

	for (const variant of iconVariants) {
		registerAction2(class extends Action2 {
			constructor() {
				super({
					id: ACTION_ID_NEW_CHAT + variant.idSuffix,
					title: localize2('chat.newEdits.label', "New Chat"),
					category: CHAT_CATEGORY,
					icon: variant.icon,
					precondition: ContextKeyExpr.and(ChatContextKeys.enabled, ChatContextKeys.location.isEqualTo(ChatAgentLocation.Chat)),
					f1: false,
					menu: [{
						id: MenuId.ChatNewMenu,
						group: '1_open',
						order: 1,
						when: ChatContextKeys.newChatButtonExperimentIcon.isEqualTo(variant.iconValue)
					}]
				});
			}

			async run(accessor: ServicesAccessor, ...args: unknown[]) {
				const executeCommandContext = isNewEditSessionActionContext(args[0]) ? args[0] : undefined;
				const context = getEditingSessionContext(accessor, args);
				await runNewChatAction(accessor, context, executeCommandContext);
			}
		});
	}

	CommandsRegistry.registerCommandAlias(ACTION_ID_NEW_EDIT_SESSION, ACTION_ID_NEW_CHAT);

	registerAction2(class NewLocalChatAction extends Action2 {
		constructor() {
			super({
				id: 'workbench.action.chat.newLocalChat',
				title: localize2('chat.newLocalChat.label', "New Local Chat"),
				category: CHAT_CATEGORY,
				icon: Codicon.plus,
				precondition: ContextKeyExpr.and(ChatContextKeys.enabled, ChatContextKeys.location.isEqualTo(ChatAgentLocation.Chat)),
				f1: false,
			});
		}

		async run(accessor: ServicesAccessor, ...args: unknown[]) {
			const executeCommandContext = isNewEditSessionActionContext(args[0]) ? args[0] : undefined;

			// Context from toolbar or lastFocusedWidget
			const context = getEditingSessionContext(accessor, args);

			// When no chat widget is open yet, opening the view resolves the
			// computed default provider (a non-local harness when the agent host
			// is enabled). Open the view, then explicitly start a local session:
			// `startNewLocalSession` cancels that in-flight default resolution so
			// the local request is honored without waiting for the agent host.
			if (!context?.chatWidget) {
				const view = await accessor.get(IViewsService).openView(ChatViewId, true) as ChatViewPane | null;
				await view?.startNewLocalSession();
				view?.focusInput();
				return;
			}

			await runNewChatAction(accessor, context, executeCommandContext, AgentSessionProviders.Local);
		}
	});

	MenuRegistry.appendMenuItem(MenuId.ChatViewSessionTitleNavigationToolbar, {
		command: {
			id: ACTION_ID_NEW_CHAT,
			title: localize2('chat.goBack', "Go Back"),
			icon: Codicon.arrowLeft,
		},
		when: ChatContextKeys.agentSessionsViewerOrientation.notEqualsTo(AgentSessionsViewerOrientation.SideBySide), // when sessions show side by side, no need for a back button
		group: 'navigation',
		order: 1
	});

	MenuRegistry.appendMenuItem(MenuId.ChatTitleBarMenu, {
		command: {
			id: ACTION_ID_NEW_CHAT,
			title: localize2('chat.newEdits.label', "New Chat"),
		},
		when: ChatContextKeys.enabled,
		group: 'b_new',
		order: -1,
	});

	registerAction2(class UndoChatEditInteractionAction extends EditingSessionAction {
		constructor() {
			super({
				id: 'workbench.action.chat.undoEdit',
				title: localize2('chat.undoEdit.label', "Undo Last Edit"),
				category: CHAT_CATEGORY,
				icon: Codicon.discard,
				precondition: ContextKeyExpr.and(ChatContextKeys.chatEditingCanUndo, ChatContextKeys.enabled),
				f1: true,
				menu: [{
					id: MenuId.ViewTitle,
					when: ContextKeyExpr.equals('view', ChatViewId),
					group: 'navigation',
					order: -3,
					isHiddenByDefault: true
				}]
			});
		}

		async runEditingSessionAction(accessor: ServicesAccessor, editingSession: IChatEditingSession) {
			await editingSession.undoInteraction();
		}
	});

	registerAction2(class RedoChatEditInteractionAction extends EditingSessionAction {
		constructor() {
			super({
				id: 'workbench.action.chat.redoEdit',
				title: localize2('chat.redoEdit.label', "Redo Last Edit"),
				category: CHAT_CATEGORY,
				icon: Codicon.redo,
				precondition: ContextKeyExpr.and(ChatContextKeys.chatEditingCanRedo, ChatContextKeys.enabled),
				f1: true,
				menu: [
					{
						id: MenuId.ViewTitle,
						when: ContextKeyExpr.equals('view', ChatViewId),
						group: 'navigation',
						order: -2,
						isHiddenByDefault: true
					}
				]
			});
		}

		async runEditingSessionAction(accessor: ServicesAccessor, editingSession: IChatEditingSession) {
			const chatService = accessor.get(IChatService);
			await editingSession.redoInteraction();
			chatService.getSession(editingSession.chatSessionResource)?.setCheckpoint(undefined);
		}
	});

	registerAction2(class RedoChatCheckpoints extends EditingSessionAction {
		constructor() {
			super({
				id: 'workbench.action.chat.redoEdit2',
				title: localize2('chat.redoEdit.label2', "Redo"),
				tooltip: localize2('chat.redoEdit.tooltip', "Reapply discarded workspace changes and chat"),
				category: CHAT_CATEGORY,
				precondition: ContextKeyExpr.and(ChatContextKeys.chatEditingCanRedo, ChatContextKeys.enabled),
				f1: true,
				menu: [{
					id: MenuId.ChatMessageRestoreCheckpoint,
					when: ContextKeyExpr.or(ChatContextKeys.lockedToCodingAgent.negate(), ChatContextKeyExprs.isAgentHostSession),
					group: 'navigation',
					order: -1
				}]
			});
		}

		async runEditingSessionAction(accessor: ServicesAccessor, editingSession: IChatEditingSession) {
			const widget = accessor.get(IChatWidgetService);

			while (editingSession.canRedo.get()) {
				await editingSession.redoInteraction();
			}

			const currentWidget = widget.getWidgetBySessionResource(editingSession.chatSessionResource);
			const requestText = currentWidget?.viewModel?.model.checkpoint?.message.text;

			// if the input has the same text that we just restored, clear it.
			if (currentWidget?.inputEditor.getValue() === requestText) {
				currentWidget?.input.setValue('', false);
			}

			currentWidget?.viewModel?.model.setCheckpoint(undefined);
			currentWidget?.focusInput();
		}
	});
}

async function runNewChatAction(
	accessor: ServicesAccessor,
	context: EditingSessionActionContext | undefined,
	executeCommandContext?: INewEditSessionActionContext,
	_sessionType?: AgentSessionProviders
) {
	const accessibilityService = accessor.get(IAccessibilityService);
	const viewsService = accessor.get(IViewsService);
	const commandService = accessor.get(ICommandService);
	const dialogService = accessor.get(IDialogService);
	const voiceSessionController = accessor.get(IVoiceSessionController);

	// Always go through the Chat view pane so New Chat works from the sessions
	// list / welcome / empty state — not only when a viewModel already exists.
	const view = await viewsService.openView(ChatViewId, true) as ChatViewPane | null;
	if (!view) {
		return;
	}

	const widget = context?.chatWidget ?? view.widget;
	const editingSession = context?.editingSession;
	const voiceTarget = voiceSessionController.targetSession.get();
	const currentSession = widget.viewModel?.sessionResource;

	const model = widget.viewModel?.model;
	if (model && !(await handleCurrentEditingSession(model, undefined, dialogService))) {
		return;
	}

	await editingSession?.stop();

	// Always start a fresh local session in the Chat view. Agent-host untitled
	// sessions can fail/hang without auth; Local is the reliable empty composer.
	await view.startNewLocalSession();

	// Hide stacked SESSIONS so New Chat is visibly a blank composer (Cursor-like).
	view.showEmptyComposer();

	const newSession = view.widget.viewModel?.sessionResource;
	if ((voiceSessionController.isConnected.get() || voiceSessionController.isConnecting.get())
		&& (!voiceTarget || (!!currentSession && isEqual(voiceTarget, currentSession)))
		&& newSession) {
		voiceSessionController.setTargetSession(newSession);
	}

	const activeWidget = view.widget;
	activeWidget.attachmentModel.clear(true);
	activeWidget.focusInput();

	accessibilityService.alert(localize('newChat', "New chat"));
	await notifyExtensionsOfNewChat(commandService);

	if (!executeCommandContext) {
		return;
	}

	if (typeof executeCommandContext.agentMode === 'boolean') {
		activeWidget.input.setChatMode(executeCommandContext.agentMode ? ChatModeKind.Agent : ChatModeKind.Edit);
	} else if (activeWidget.input.currentModeKind === ChatModeKind.Edit) {
		activeWidget.input.setChatMode(ChatModeKind.Agent);
	}

	if (executeCommandContext.inputValue) {
		if (executeCommandContext.isPartialQuery) {
			activeWidget.setInput(executeCommandContext.inputValue);
		} else {
			activeWidget.acceptInput(executeCommandContext.inputValue);
		}
	}
}

async function notifyExtensionsOfNewChat(commandService: ICommandService): Promise<void> {
	try {
		await commandService.executeCommand('shiyuncode.agent.onWorkbenchNewChat');
	} catch {
		// Extension may be missing / not yet activated — ignore.
	}
}

